document.addEventListener("htmx:load",c=>{const s=c.detail.elt,a='[data-id="parent"]';s.querySelectorAll('[data-id="tenant"]').forEach(t=>{const e=t.closest("form").querySelector(a);e&&t.addEventListener("change",()=>{const r=new URL(location.href);r.searchParams.set("tenant",t.value),e.disabled=!0,fetch(r).then(n=>n.text()).then(n=>{const l=new DOMParser().parseFromString(n,"text/html").querySelector(a);e.innerHTML=l?.innerHTML||"",e.disabled=!1,e.closest(".form-row").hidden=e.childElementCount<=1,e.dispatchEvent(new Event("change"))})})})});
